citations.cypher:
CALL {
  // (1) Gate with the largest volume of person traffic
  MATCH (e:Event)-[:DETECTED_BY]->(c:Camera)-[:LOCATED_AT]->(l:Location)
  WHERE e.event_type IN ['person_entry', 'person_exit']
    AND e.timestamp_utc >= '2025-12-08T00:00:00Z' AND e.timestamp_utc < '2025-12-09T00:00:00Z'
  RETURN l.name AS location, count(e) AS volume, 'Person Traffic' AS category
  ORDER BY volume DESC
  LIMIT 1
}
UNION
CALL {
  // (2) Gate with the most car traffic
  MATCH (e:Event)-[:DETECTED_BY]->(c:Camera)-[:LOCATED_AT]->(l:Location)
  WHERE e.event_type IN ['car_entry', 'car_exit']
    AND e.timestamp_utc >= '2025-12-08T00:00:00Z' AND e.timestamp_utc < '2025-12-09T00:00:00Z'
  RETURN l.name AS location, count(e) AS volume, 'Car Traffic' AS category
  ORDER BY volume DESC
  LIMIT 1
}
UNION
CALL {
  // (3) Public area with the highest crowd density spikes
  MATCH (ch:CrowdHour)-[:AT_CAMERA]->(c:Camera)-[:LOCATED_AT]->(l:Location)
  WHERE ch.hour_utc >= '2025-12-08T00:00:00Z' AND ch.hour_utc < '2025-12-09T00:00:00Z'
  RETURN l.name AS location, max(ch.peak_hc) AS volume, 'Crowd Density' AS category
  ORDER BY volume DESC
  LIMIT 1
}
RETURN category, location, volume

